    {"id": "chart", "title": "Chart Structure & Metadata", "color": "sky", "blurb": "Chart.yaml, templates, dependencies, schemas and package layout."},
    {"id": "templates", "title": "Templates, Values & Reuse", "color": "mint", "blurb": "Go templates, helpers, values, functions and rendering."},
    {"id": "release", "title": "Install, Upgrade & Rollback", "color": "peach", "blurb": "Release lifecycle, hooks, tests and safe deployment."},
