TOPICS = build_practice_catalog([
    ("helm-chart-structure", "Chart Directory & Required Files", "chart", "basic", "A chart packages templates, defaults, metadata and optional dependencies. Keep application templates, tests and documentation organized so maintainers can review rendered output.", "Chart.yaml · values.yaml · templates/ · charts/ · templates/NOTES.txt"),
    ("helm-chart-yaml", "Chart.yaml: Name, Version & App Version", "chart", "basic", "Chart version identifies the package; appVersion describes the application and is informational. Follow semantic versioning for chart interface changes and pin dependencies.", "apiVersion: v2\nname: payments\nversion: 1.4.0\nappVersion: \"2.7.1\""),
    ("helm-chart-types", "Application Charts vs Library Charts", "chart", "intermediate", "Application charts install Kubernetes resources; library charts expose reusable named templates and should not render resources directly. Use libraries for stable shared conventions.", "type: library"),
    ("helm-values", "Values Files & Environment Overrides", "templates", "basic", "Values supply configuration to templates and can be layered from defaults through environment-specific files and CLI flags. Keep environment overrides small and review precedence explicitly.", "helm upgrade --install payments ./chart -f values-prod.yaml"),
    ("helm-values-precedence", "Helm Values Precedence & Merge Behavior", "templates", "intermediate", "Higher-precedence command-line values override files and defaults; map values merge while list behavior can surprise operators. Inspect computed values before rollout.", "helm get values payments -n prod --all"),
    ("helm-template-basics", "Go Template Syntax & Whitespace", "templates", "basic", "Helm uses Go templates with actions, pipelines and whitespace trimming. Whitespace controls can affect YAML indentation, so render templates frequently and inspect the actual manifest.", "{{ .Values.replicaCount }}"),
    ("helm-helpers", "Named Templates & _helpers.tpl", "templates", "intermediate", "Named templates centralize names, labels and common snippets. Prefix helper names with the chart to avoid collisions when charts are composed.", "{{- define \"payments.fullname\" -}}...{{- end -}}"),
    ("helm-include", "include vs template & Indentation", "templates", "intermediate", "`include` returns rendered text that can be piped through indent or nindent; `template` writes directly. Use include for YAML fragments requiring correct indentation.", "labels:\n{{ include \"payments.labels\" . | nindent 2 }}"),
    ("helm-scope", "Dot Scope, with & range", "templates", "intermediate", "`.` is the current scope and changes inside with/range blocks; `$` retains the root context. Pass context deliberately to helpers to avoid missing values.", "{{- $root := . -}}{{ range .Values.services }}{{ include \"payments.labels\" $root }}{{ end }}"),
    ("helm-conditionals", "if, else & Conditional Resources", "templates", "basic", "Conditionals render resources only when values meet explicit criteria. Use booleans for enable switches and avoid ambiguous truthiness from strings or empty collections.", "{{- if .Values.ingress.enabled }}kind: Ingress{{- end }}"),
    ("helm-default-required", "default, required & Fail-Fast Values", "templates", "intermediate", "`default` supplies a fallback and `required` fails rendering when a value is missing. For meaningful zero or false values, validate with JSON schema rather than relying on default's empty-value semantics.", "{{ required \"image.repository is required\" .Values.image.repository }}"),
    ("helm-dict-list", "Dictionaries, Lists & Merge Helpers", "templates", "intermediate", "Template functions manipulate dictionaries and lists; `merge` and `deepCopy` have reference semantics that can cause accidental mutation. Keep transformations local and test overrides.", "mergeOverwrite (deepCopy .Values.defaults) .Values.service"),
    ("helm-tpl", "tpl: Render Trusted Values as Templates", "templates", "advanced", "`tpl` evaluates a string value as a template, enabling dynamic config but also executing template logic from that value. Use only for trusted chart values and tightly control inputs.", "tpl .Values.extraConfig ."),
    ("helm-capabilities", "Capabilities, API Versions & Kubernetes Versions", "templates", "intermediate", "Capabilities expose cluster Kubernetes version and available API groups to templates. Prefer stable APIs and test rendering against supported versions rather than scattering fragile version branches.", "helm template payments ./chart --api-versions networking.k8s.io/v1"),
    ("helm-json-schema", "values.schema.json & Type Validation", "chart", "intermediate", "A JSON schema validates values types, required fields, enums and ranges before rendering. Schema messages should tell chart users how to fix an invalid configuration.", "helm lint ./chart -f values-prod.yaml"),
    ("helm-crds", "CRDs, crds/ Directory & Upgrade Caveats", "chart", "advanced", "CRDs placed in crds/ install on first release install but Helm does not upgrade or delete them. Manage CRD lifecycle explicitly and protect custom resources during operator upgrades.", "Install CRD chart separately, then upgrade controller chart"),
    ("helm-dependencies", "Chart Dependencies & Conditions", "chart", "intermediate", "Dependencies are pinned in Chart.yaml and locked in Chart.lock. Conditions and tags can enable subcharts; `helm dependency update` changes lock state while build resolves locked packages.", "helm dependency build ./chart"),
    ("helm-subcharts", "Subchart Values & Global Configuration", "chart", "intermediate", "Parent charts configure subchart values under the dependency name or alias; global values are shared but can create hidden coupling. Prefer explicit subchart interfaces.", "redis.auth.enabled: true"),
    ("helm-alias", "Dependency Aliases & Multiple Instances", "chart", "advanced", "Aliases let a parent include the same chart under multiple identities with separate values. Names, selectors, release ownership and shared resources must remain distinct.", "alias: cache-blue"),
    ("helm-package", "Package, Sign & Verify Charts", "chart", "intermediate", "`helm package` creates a versioned archive; provenance files can authenticate package origin when signed. Verify chart version, digest and provenance before using external packages.", "helm package ./chart --sign --key 'release-key' --keyring pubring.gpg"),
    ("helm-repository", "HTTP Chart Repositories & index.yaml", "chart", "basic", "Traditional chart repositories expose packages and an index.yaml catalog. Repository URLs and credentials should use TLS and protected configuration; chart versions remain immutable.", "helm repo add internal https://charts.example.com"),
    ("helm-oci", "OCI Registries for Helm Charts", "chart", "intermediate", "Helm can push and pull charts using OCI registries. OCI storage aligns chart distribution with image registry access controls and digest-based artifact workflows.", "helm push payments-1.4.0.tgz oci://registry.example.com/charts"),
    ("helm-install", "Install Releases & Namespace Scope", "release", "basic", "`helm install` creates a named release in a namespace; `--create-namespace` can create that namespace. Release names, values and history are scoped to the chosen context and namespace.", "helm install payments ./chart -n prod --create-namespace"),
    ("helm-upgrade", "Upgrade --install & Atomic Waits", "release", "basic", "`helm upgrade --install` handles first install and later upgrades. `--wait`, timeout and `--atomic` change readiness waiting and failure rollback behavior; they cannot guarantee application correctness.", "helm upgrade --install payments ./chart -n prod --atomic --wait --timeout 5m"),
    ("helm-dry-run", "Render, Diff & Review Before Applying", "release", "intermediate", "Render manifests with the exact values and Kubernetes version, then inspect a diff against live resources. Redact Secrets and avoid sending plaintext values to shared logs.", "helm template payments ./chart -f values-prod.yaml | kubectl diff -f -"),
    ("helm-history", "Release Revisions & History", "release", "basic", "Helm records release revisions and values in Secrets by default. History helps identify the deployed manifest and revision but may contain sensitive configuration.", "helm history payments -n prod"),
    ("helm-rollback", "Rollback & Forward-Fix Decisions", "release", "basic", "Rollback reapplies a prior release revision as a new revision. Validate external schema or data changes before rollback and align Git desired state afterward.", "helm rollback payments 12 -n prod --wait"),
    ("helm-uninstall", "Uninstall, Keep-History & Data Safety", "release", "intermediate", "Uninstall removes release-managed resources, which may include persistent claims depending on templates and policies. Understand retention, CRDs and external side effects before deletion.", "helm uninstall payments -n prod --keep-history"),
    ("helm-hooks", "Hooks, Weights & Hook Cleanup", "release", "advanced", "Hooks run annotated resources around lifecycle events such as pre-upgrade or post-install. Weight and delete policies order and clean up hooks; hook failures can block a release.", "helm.sh/hook: pre-upgrade,pre-install"),
    ("helm-tests", "helm test & Release Verification", "release", "intermediate", "Chart tests are hook Jobs that validate a deployed release. They should test service behavior and dependencies, be repeatable and clean up safely.", "helm test payments -n prod --logs"),
    ("helm-notes", "NOTES.txt & Operator Handoff", "release", "basic", "NOTES.txt prints post-install guidance such as access commands, endpoints and verification steps. Never print secrets or instructions that assume unsafe public exposure.", "helm get notes payments -n prod"),
    ("helm-history-secrets", "Helm Storage Drivers & Release Secrets", "release", "advanced", "The Secret storage driver stores release records in Kubernetes Secrets; RBAC around these secrets can expose rendered manifests and values. Plan retention and permissions accordingly.", "kubectl get secrets -n prod -l owner=helm"),
    ("helm-secrets", "Secrets in Values & External Secret Patterns", "security", "advanced", "Plaintext values can persist in shell history, CI artifacts, release metadata and logs. Use external secret controllers or encrypted values workflows and verify how rendered Secret manifests are stored.", "Reference an existing Secret by name rather than commit a password in values.yaml"),
    ("helm-rbac", "RBAC Templates & Least Privilege", "security", "intermediate", "Charts should render only required service accounts, roles and bindings. Avoid cluster-admin defaults and make optional cluster-wide resources explicit with narrow permissions.", "Create namespaced Role with get/list only for required ConfigMaps"),
    ("helm-security-context", "Pod Security Contexts & Secure Defaults", "security", "intermediate", "Chart defaults should support non-root execution, read-only root filesystem, dropped capabilities and seccomp where compatible. Expose overrides without weakening secure defaults silently.", "runAsNonRoot: true · allowPrivilegeEscalation: false"),
    ("helm-image-pinning", "Image Tags, Digests & Pull Policies", "security", "intermediate", "Image configuration should be explicit; digests make content immutable while tags are convenient release labels. Avoid implicit latest and choose pull policy intentionally.", "image: registry.example/payments@sha256:..."),
    ("helm-supply-chain", "Chart Provenance, Dependencies & Scanning", "security", "advanced", "Charts and dependencies are software supply-chain inputs. Pin versions, verify provenance, scan rendered workloads and track ownership of external charts before installation.", "helm dependency build → verify archive → render → policy scan"),
    ("helm-lint", "helm lint & Chart Validation", "operations", "basic", "`helm lint` checks chart structure, metadata, values and common template problems. Combine it with render tests over supported value combinations and Kubernetes API versions.", "helm lint ./chart --strict"),
    ("helm-unittest", "Unit-Test Templates & Golden Manifests", "operations", "intermediate", "Template unit tests assert rendered resource names, values and optional resources. Golden tests catch broad changes but need review when expected output changes intentionally.", "helm unittest ./chart"),
    ("helm-schema-tests", "Test Values Matrix & Schema Boundaries", "operations", "intermediate", "A values matrix tests minimal, production, feature-enabled and invalid configurations. Validate schema rejection and ensure every supported mode renders complete manifests.", "helm template demo ./chart -f tests/values-minimal.yaml"),
    ("helm-diff-plugin", "Release Diff & Change Review", "operations", "intermediate", "A diff plugin or rendered kubectl diff compares desired manifests with a release or live state. Review replacements, immutable field changes, hooks, deletion and secret handling before upgrade.", "helm diff upgrade payments ./chart -n prod -f values-prod.yaml"),
    ("helm-debug-template", "Debug Failed Templates & YAML Output", "operations", "intermediate", "Use `helm template --debug` and inspect whitespace, types, missing values and API versions. Errors often come from scope changes inside range/with or a string where a Boolean was expected.", "helm template payments ./chart --debug --show-only templates/deployment.yaml"),
    ("helm-release-status", "Release Status, Pending States & Recovery", "operations", "advanced", "A release can remain pending after interrupted upgrades or failed hooks. Inspect status, history, jobs and stored release records before deciding whether to rollback or repair.", "helm status payments -n prod --show-resources"),
    ("helm-kustomize", "Helm with Kustomize", "operations", "intermediate", "Kustomize can render Helm charts when helm inflation is enabled, then apply patches and overlays. Keep chart version and value sources explicit and inspect the final rendered tree.", "kustomize build --enable-helm overlays/prod"),
    ("helm-argocd", "Helm Charts with Argo CD", "operations", "intermediate", "Argo CD can use Helm as a manifest renderer while Git remains desired state. Argo CD manages reconciliation; Helm release history semantics differ from a direct Helm CLI release.", "Application source: chart repo + chart version + target revision"),
    ("helm-flux", "HelmRelease with Flux", "operations", "intermediate", "Flux Helm Controller reconciles HelmRelease custom resources from Git, including chart source, values and remediation. Model chart source and values as versioned dependencies.", "HelmRelease → HelmRepository → pinned chart version"),
    ("helm-api-compatibility", "Kubernetes API Compatibility & Capabilities", "operations", "advanced", "Charts must support declared Kubernetes versions and removed API migrations. Render against target API capabilities and test CRDs/controllers separately from templates.", "helm template --kube-version 1.30.0 --api-versions policy/v1"),
    ("helm-lookup", "lookup Function & Cluster-Dependent Rendering", "templates", "advanced", "`lookup` queries live cluster state during server-side rendering and makes output dependent on current permissions and state. Prefer explicit values for reproducible GitOps charts.", "helm template --dry-run=server"),
    ("helm-library-labels", "Labels, Annotations & Selector Stability", "templates", "intermediate", "Standard labels support ownership, dashboards and selectors; selector labels should remain stable across releases. Put mutable chart version labels in pod metadata, not immutable workload selectors.", "app.kubernetes.io/name · instance · component · managed-by"),
    ("helm-pvc", "Persistent Volumes & Data Retention", "release", "advanced", "Charts that create PVCs must communicate storage class, access mode, expansion and uninstall behavior. Preserve application data through upgrades and avoid accidental claim deletion.", "helm uninstall may leave PVC by policy; verify reclaim and retention settings"),
    ("helm-crd-testing", "CRD Upgrade & Custom Resource Ordering", "chart", "advanced", "CRDs and their controllers often have separate version lifecycles. Install CRDs before custom resources, test schema compatibility and plan rollback constraints for stored objects.", "Upgrade CRD package first, wait for Established, then upgrade operator"),
    ("helm-concurrency", "Concurrent Helm Operations & Locking", "release", "advanced", "Concurrent upgrades of the same release can conflict or leave pending state. Serialize deploys per release and coordinate manual CLI changes with GitOps controllers.", "CI concurrency group: cluster + namespace + release"),
    ("helm-drift", "Drift, Manual kubectl Changes & Reconciliation", "operations", "intermediate", "Manual edits to Helm-managed resources can be overwritten by the next upgrade or GitOps reconciliation. Compare live state with rendered desired state and commit intended changes.", "helm get manifest payments -n prod; compare with current chart render"),
    ("helm-hooks-idempotence", "Idempotent Migration Hooks & Failure Recovery", "release", "advanced", "Migration hooks should be safe to retry, version-aware and observable. A failed hook may prevent upgrade while leaving external database state changed; define forward recovery.", "Job checks schema version, applies migration transactionally, records completion"),
    ("helm-values-schema", "Document Values & Deprecate Safely", "chart", "intermediate", "Values are a user-facing API. Document type, default, impact and deprecation path; maintain compatibility across chart upgrades and provide migration notes for renamed keys.", "Deprecate old key with warning; map to new key for one supported release"),
    ("helm-capacity", "Requests, Limits & Autoscaling Values", "templates", "intermediate", "Chart defaults for resources affect scheduling and reliability. Expose requests and limits as structured values and validate compatible HPA settings so replicas are not managed by two sources.", "resources.requests.cpu: 100m; autoscaling.enabled: true"),
], "HELM", "A Helm chart is a versioned interface for Kubernetes resources: validate values, render before rollout, and understand the release lifecycle.")

